{
  "findings": [
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 bucket lacks a lifecycle configuration",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The logs bucket has versioning and KMS encryption but no lifecycle rule to manage stored objects over time. Without lifecycle management, logs remain indefinitely in the default storage tier."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "logs" {
  bucket = "${local.resource_prefix.value}-logs"
  acl    = "log-delivery-write"
  versioning {
    enabled = true
  }
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = "${aws_kms_key.logs_key.arn}"
      }
    }
  }
  lifecycle_rule {
    id      = "archive-logs"
    enabled = true

    transition {
      days          = 90
      storage_class = "STANDARD_IA"
    }
  }
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-logs"
    Environment = local.resource_prefix.value
    }, {
  })
}
",
  "fix_summary": "Added an enabled S3 lifecycle rule that transitions log objects to STANDARD_IA after 90 days. The existing versioning, customer-managed KMS encryption, ACL, tags, and other settings were preserved."
}
